INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Datensatz dasselbe wie eine Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "Datensatz ist eine Zeile, Datenbank eine Sammlung"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Datensatz?', 3, '[{"text": "Einzelne Daten speichern", "correct": true, "because": "Repräsentiert eine Entität"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile hat ein Datensatz?', 5, '[{"text": "Felder", "correct": true, "because": "Einzelne Datenpunkte"}, {"text": "Werte", "correct": true, "because": "Inhalte der Felder"}, {"text": "Monitorauflösung", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datensatz ist eine Zeile in einer Tabelle. b) Er enthält immer alle Daten einer Datenbank.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit Datensätzen?', 4, '[{"text": "Felddefinitionen", "correct": false, "because": "Struktur entscheidend"}, {"text": "Datenintegrität", "correct": false, "because": "Konsistenz wichtig"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Datensatz mehrere Tabellen umfassen kann?', 2, '[{"text": "Nein", "correct": true, "because": "Eine Zeile pro Tabelle"}, {"text": "Ja", "correct": false, "because": "Tabellenübergreifend nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Befehl fügt einen Datensatz in eine Datenbank ein?', 3, '[{"text": "INSERT", "correct": true, "because": "SQL-Befehl für Hinzufügen"}, {"text": "SELECT", "correct": false, "because": "Abfragen"}, {"text": "CREATE", "correct": false, "because": "Tabellen erstellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein Datensatz?', 5, '[{"text": "Eindeutigkeit", "correct": true, "because": "Durch Schlüssel gesichert"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Felder gefüllt"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Merkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Datensatz repräsentiert eine Entität. b) Er ist immer unstrukturiert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft strukturiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Datensatz?', 4, '[{"text": "Tabellenstruktur", "correct": false, "because": "Definiert Felder"}, {"text": "Datenbank", "correct": false, "because": "Speicherort nötig"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Datensatz immer vollständig?', 2, '[{"text": "Nein", "correct": true, "because": "Felder können leer sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen kann ich mit einem Datensatz durchführen?', 4, '[{"text": "Einfügen", "correct": true, "because": "Neue Daten hinzufügen"}, {"text": "Aktualisieren", "correct": true, "because": "Daten ändern"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Datensatz nur Text enthält. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Zahlen, Bilder möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Datensatz?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Konsistenz sichern"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Richtigkeit wichtiger"}, {"text": "Minimale Größe", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Datensatz kann eindeutig sein. b) Er ist immer unabhängig von Tabellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist tabellenabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten können in einem Datensatz gespeichert werden?', 5, '[{"text": "Text", "correct": true, "because": "String-Daten"}, {"text": "Zahlen", "correct": true, "because": "Numerische Werte"}, {"text": "Farbcodes", "correct": false, "because": "Nicht typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwaltung unwichtig?', 3, '[{"text": "Schlüssel", "correct": false, "because": "Eindeutigkeit sichern"}, {"text": "Datenformat", "correct": false, "because": "Verarbeitung definieren"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Datensatz leer sein?', 3, '[{"text": "Ja", "correct": true, "because": "Felder können NULL sein"}, {"text": "Nein", "correct": false, "because": "Nicht zwingend gefüllt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Datensatz nur digitale Daten enthält?', 2, '[{"text": "Ja", "correct": true, "because": "Datenbankfokus ist digital"}, {"text": "Nein", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Primärschlüssel bei einem Datensatz?', 4, '[{"text": "Eindeutigkeit sichern", "correct": true, "because": "Identifiziert Datensatz"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Sekundär"}, {"text": "Grafik verbessern", "correct": false, "because": "Irrelevant"}]');
